//! Actual native targeted/closed utility fold on the SAME retained model.
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,reactive_global_source::Source,key_policy_control::{self as kc,Control}};
use std::{cell::Cell,io,path::Path,sync::Arc};
struct Work<'a>{budget:&'a Arc<Budget>,poll:&'a dyn Fn()->io::Result<()>,temporary:[usize;2]}
impl Control for Work<'_>{type Error=io::Error;const CHECKED:bool=true;fn checkpoint(&mut self)->io::Result<()>{self.budget.require().map_err(|m|io::Error::new(io::ErrorKind::OutOfMemory,m))?;(self.poll)()}fn reserve(&mut self,n:usize)->io::Result<()>{self.checkpoint()?;self.budget.charge(n).map_err(|m|io::Error::new(io::ErrorKind::OutOfMemory,m))}fn temporary(&mut self,slot:usize,n:usize)->io::Result<()>{let old=*self.temporary.get(slot).ok_or(io::ErrorKind::InvalidInput)?;if n>old{self.reserve(n-old)?;self.temporary[slot]=n;}Ok(())}fn overflow(&mut self)->io::Error{self.budget.deny();io::ErrorKind::OutOfMemory.into()}fn allocation_failed(&mut self)->io::Error{self.budget.deny();io::ErrorKind::OutOfMemory.into()}}
struct Lines<'a>{inputs:&'a dm_analysis::policy_inputs::PolicyInputs,root:&'a Path,missing:Cell<bool>}
impl crate::reactive_closure_report::Lines for Lines<'_>{fn line(&self,relative:&str,line:u32)->Option<&str>{let file=self.inputs.files().find(|file|file.path().strip_prefix(self.root).ok()==Some(Path::new(relative)))?;let text=match file.view(dm_analysis::policy_inputs::TextView::AnalyzeRaw){Ok(text)=>text,Err(_)=>{self.missing.set(true);return None}};text.split('\n').nth(usize::try_from(line).ok()?.checked_sub(1)?)}}
pub fn render(inputs:&dm_analysis::policy_inputs::PolicyInputs,root:&Path,pages:&dyn crate::reactive_raw_policy_pages::RawPolicyPages,order:&std::collections::HashMap<String,usize>,budget:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,body:&crate::reactive_original_source::UtilityBodyBorrower<'_>,patterns:&dyn crate::native_pattern::Provider,emit:&mut dyn FnMut(&str)->io::Result<()>)->Result<(),Failure>{
 let scratch=Budget::scoped_temporaries(budget).map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))?;
 let pending=(||{let source=crate::reactive_original_source::ReadSource::native(inputs,root,budget)?.with_raw_policy_pages(pages,order).with_checkpoint(poll).with_utility_body_borrower(body);source.with_budget(&scratch,|source|{source.require()?;let mut check=||poll();let facts=crate::reactive_policy_facts_native::PolicyFacts::capture(source,&mut check)?;let globals=crate::reactive_global_facts_native::NativeGlobals::build_from(source,||poll())?;let auto=crate::auto_tracking_native::NativeCandidates::capture_original(source,&facts,&globals)?;let owned=source.dependency_marker_rows()?;let mut control=Work{budget:&scratch,poll,temporary:[0;2]};let mut markers=Vec::new();for row in &owned.markers{kc::row(&mut control,&mut markers).map_err(Failure::Operational)?;markers.push(crate::declare_policy::Marker{name:&row.name,rel:&row.rel,line:row.line,body:&row.body,args:&row.args,body_offset:row.body_offset,line_starts:&row.line_starts});}let defines=source.dependency_defines()?;let lines=Lines{inputs,root,missing:Cell::new(false)};
  crate::reactive_dependency_native::analyze_utility_pair(source,&facts,&globals,&markers,&defines,&auto,poll,|targeted,closed|{let text=crate::reactive_closure_report::report_admitted(crate::reactive_dependency_view::Analysis::Owned(targeted),crate::reactive_dependency_view::Analysis::Owned(closed),&lines,patterns,&mut control).map_err(Failure::Operational)?;if lines.missing.get(){return Err("closure raw source view was not actually captured".into())}emit(&text).map_err(Failure::Operational)})?;source.require()?;Ok(())})})();
 if pending.is_err(){scratch.keep_failed_scratch()}drop(scratch);if matches!(&pending,Err(Failure::Operational(_))){return pending}budget.require().map_err(|m|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,m)))?;poll()?;pending
}
